CREATE TABLE toilet_review(review_id BIGINT PRIMARY KEY, review_key CHAR(36) NOT NULL UNIQUE, toilet_id BIGINT NOT NULL, author_user_id BIGINT NULL, author_detached BOOLEAN NOT NULL DEFAULT FALSE, satisfaction TINYINT NOT NULL, cleanliness TINYINT NOT NULL, paper_available BOOLEAN NOT NULL, wait_minutes SMALLINT NULL, content VARCHAR(200) NULL, version BIGINT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY(author_user_id) REFERENCES app_user(user_id) ON DELETE SET NULL);
